table(['Resultado diario','Asociación ajustada con lluvia','IC del 95%','p Holm'],rows,[147,120,125,98])
p('Los intervalos contienen cero. Las estimaciones puntuales son positivas, pero no justifican afirmar que la lluvia aumente de forma demostrada el volumen, la duración o las propinas. Los intervalos son puntuales; la corrección de Holm se aplica a los tres p-valores.')
p('La lectura exige prudencia: al excluir los cinco días más influyentes, un intervalo exploratorio deja de contener cero; el modelo con volumen del día anterior estima una asociación menor. Esta sensibilidad impide presentar una conclusión categórica sobre la lluvia.')
p('Aplicación práctica','CallES')
p('Usar el dashboard para identificar cuándo y dónde se concentra la actividad, comparar perfiles horarios y comprobar si una diferencia aparente se mantiene al seleccionar otro mes o borough. Cualquier decisión operativa basada específicamente en lluvia necesitaría datos horarios y validación adicional.')
heading('2. Objetivos, preguntas e hipótesis')
p('<b>Objetivo general.</b> Describir la movilidad registrada de los taxis amarillos y examinar su asociación con el contexto meteorológico mediante un proceso trazable de limpieza, análisis y visualización.')
table(['Pregunta','Indicador','Hipótesis nula'],[['¿Varía la actividad con lluvia?','Viajes válidos diarios estimados','Coeficiente del indicador de lluvia igual a cero en el modelo logarítmico de volumen.'],['¿Varía la duración?','Duración media diaria ponderada','Coeficiente de lluvia igual a cero, ajustando también por distancia media.'],['¿Varían las propinas?','100 × suma de propinas / suma de tarifa base en pagos con tarjeta','Coeficiente de lluvia igual a cero, en puntos porcentuales.']],[145,160,185])
p('<b>Objetivos específicos.</b> Detectar incidencias de calidad; armonizar fechas y unidades; describir distribuciones y patrones temporales y territoriales; estimar asociaciones con incertidumbre; construir un dashboard que permita explorar los resultados sin modificar código.')
p('<b>Delimitación.</b> El estudio se refiere a taxis amarillos registrados por TLC, no a Uber, Lyft, taxis verdes o toda la movilidad de Nueva York. El término actividad se refiere a viajes realizados y registrados. No equivale a demanda total ni a número de personas únicas.')
p('<b>Criterio de interpretación.</b> Se informa tamaño de asociación, intervalo y p-valor ajustado. Un resultado no significativo puede reflejar una asociación pequeña, variabilidad o limitaciones de medición; no prueba que el clima sea irrelevante.')
heading('3. Fuentes, muestreo y trazabilidad')
p('<b>Fuente 1: NYC Taxi and Limousine Commission.</b> Se descargan los doce archivos mensuales oficiales de 2024, que contienen 41.169.720 registros. Incluyen inicio y fin de viaje, distancia, zonas, tarifa, forma de pago y propinas. El catálogo data.gov identifica el conjunto; la descarga mensual procede de la distribución oficial TLC.')
p('<b>Fuente 2: NOAA / NCEI.</b> Global Surface Summary of the Day, estación LaGuardia 72503014732. Se utiliza 2024 y el primer día de 2025 para cubrir el límite temporal al convertir horas locales a UTC. Temperatura, viento, visibilidad, precipitación e indicadores de fenómenos se integran por día UTC.')
p('<b>Fuente auxiliar.</b> La tabla oficial Taxi Zone Lookup traduce los identificadores de zonas a nombres y boroughs. Pertenece a TLC; no se cuenta como segunda fuente independiente.')
p('<b>Diseño muestral.</b> Se seleccionan 50.000 filas aleatorias sin reemplazo de cada mes antes de limpiar, usando semilla 202400 + número de mes. El extracto bruto de 600.000 registros se incluye íntegro en el repositorio con los valores originales y dos campos de trazabilidad: mes de archivo y fila de origen. Los archivos mensuales completos se pueden volver a descargar con el script.')
p('<b>Ponderación.</b> Para el mes m, cada fila representa N_m / 50.000 registros fuente. Por tanto, el total de viajes válidos se estima como la suma de pesos de los registros conservados. Las medias son sumas ponderadas divididas por la suma de pesos; los cuantiles se obtienen sobre la distribución acumulada ponderada. No se presenta la misma muestra mensual como si todos los meses tuvieran el mismo volumen real.')
p('El manifiesto conserva URL, filas fuente, semilla y SHA-256 por archivo. La muestra bruta facilita una reproducción ligera sin volver a descargar los aproximadamente 41 millones de registros.','SmallES')
heading('4. Calidad de datos y decisiones de limpieza')
p('Se aplican reglas de plausibilidad explícitas y ordenadas. Las incidencias pueden superponerse; las exclusiones adicionales cuentan solamente filas todavía conservadas al aplicar cada regla.')
table(['Regla','Incidencias','Exclusiones adicionales'],[[r.regla,fmt(r.incidencias,0),fmt(r.exclusiones_adicionales,0)] for r in audit.itertuples()],[310,80,100])
p(f'Además, se excluyen {v["horas_DST_ambiguas_o_inexistentes_excluidas"]} horas locales ambiguas o inexistentes por cambios de hora y {fmt(v["filas_dias_UTC_parciales_excluidas"],0)} filas correspondientes a días UTC parciales en los extremos. No se inventan horas para resolver ambigüedades. El conjunto final conserva el {fmt(100*s["n"]/600000,2)}% del extracto inicial.')
missing=q[q.ausentes.gt(0)].sort_values('ausentes',ascending=False).head(7)
table(['Variable con ausencias','Ausencias','Porcentaje'],[[r.variable,fmt(r.ausentes,0),fmt(r.porcentaje,2)+'%'] for r in missing.itertuples()],[290,100,100])
p('Los pasajeros ausentes se conservan como ausentes, porque el análisis no depende de imputarlos. La tasa de propina es deliberadamente nula para pagos que no son con tarjeta. Los códigos NOAA de ausencia se convierten a nulos, nunca a ceros. Las zonas no identificadas se etiquetan como Desconocido.')
p('No se detectan coincidencias exactas de contenido entre las filas válidas muestreadas. Un identificador compuesto por mes de archivo y fila de origen garantiza trazabilidad y unicidad, sin afirmar que TLC publique un ID único del viaje.','SmallES')
heading('5. Integración y transformación')
p('<b>Fechas.</b> Los timestamps TLC se interpretan en America/New_York, con horario de verano. GSOD utiliza el día UTC. Se convierte la hora de recogida a UTC antes de extraer la fecha. Unir directamente la fecha local con el día meteorológico UTC asignaría incorrectamente parte de los viajes nocturnos.')
p('<b>Cardinalidad.</b> La tabla meteorológica tiene una fila por fecha. La unión es muchos-a-uno y se comprueba que no cambie el número de viajes y que no existan correspondencias ausentes. Las tablas de zonas se validan también como muchos-a-uno.')
p('<b>Periodo final.</b> Se conservan 365 días completos, del 2 de enero al 31 de diciembre UTC de 2024. Se excluye el 1 de enero UTC y el 1 de enero de 2025 UTC porque el periodo definido por los archivos de 2024 en hora local no cubre esos días enteros.')
table(['Variable derivada','Definición'],[['duracion_min','Diferencia entre fin e inicio, expresada en minutos.'],['distancia_km','trip_distance × 1,609344.'],['velocidad_kmh','distancia_km / (duracion_min / 60). Es velocidad media del viaje, no velocidad instantánea.'],['temperatura_c','(TEMP - 32) × 5/9.'],['viento_kmh','WDSP × 1,852.'],['precipitacion_mm','PRCP × 25,4; ausencia si código NOAA 99,99 o atributo I.'],['lluvia_indicada','Segunda posición de FRSHTT igual a 1. Un 0 significa no indicado o no reportado.']],[145,345])
p('El indicador de lluvia no mide la intensidad y no implica que lloviera durante cada viaje. La precipitación diaria puede incluir parte del día anterior según el periodo de observación de origen. Por eso la asociación se interpreta como contexto diario, no exposición exacta.','SmallES')
p('<b>La lógica de los cálculos.</b> No se promedian medias de grupos como si todos tuvieran el mismo tamaño. Para duración se suma peso × minutos y se divide por suma de pesos. Para propinas se divide la suma de propinas de tarjeta por la suma de tarifa base de tarjeta. Las hojas Calculos y Razonamiento desarrollan qué pregunta responde cada expresión y qué interpretación sería incorrecta.')
p('<b>Ejemplo didáctico.</b> Dos registros duran 10 y 20 minutos y representan 60 y 80 viajes. La media ponderada es (60 × 10 + 80 × 20) / 140 = 15,71 min; la media simple sería 15 min. Son valores ilustrativos, no registros del dataset.')
